const express = require('express');
const crypto = require('crypto');
const helmet = require('helmet');

const app = express();
app.use(helmet());
app.use(express.json({ limit: '1kb' }));

const SECRET_KEY = crypto.randomBytes(32);
const TOKEN_STORE = new Map();

// Generate HMAC token for a given payload
function generateToken(payload) {
  const data = JSON.stringify(payload);
  const hmac = crypto.createHmac('sha256', SECRET_KEY);
  hmac.update(data);
  const signature = hmac.digest('hex');
  return { data, signature };
}

// Constant-time comparison to prevent timing attacks
function safeCompare(a, b) {
  // Validate inputs are hex strings
  if (typeof a !== 'string' || typeof b !== 'string') {
    return false;
  }
  if (!/^[0-9a-f]+$/i.test(a) || !/^[0-9a-f]+$/i.test(b)) {
    return false;
  }

  // Ensure both inputs are buffers of equal length
  const bufA = Buffer.from(a, 'hex');
  const bufB = Buffer.from(b, 'hex');

  // Strict length check before comparison
  if (bufA.length !== bufB.length) {
    return false;
  }
  return crypto.timingSafeEqual(bufA, bufB);
}

// Verify token integrity
function verifyToken(data, providedSignature) {
  if (typeof data !== 'string' || typeof providedSignature !== 'string') {
    return false;
  }
  const hmac = crypto.createHmac('sha256', SECRET_KEY);
  hmac.update(data);
  const expectedSignature = hmac.digest('hex');
  return safeCompare(expectedSignature, providedSignature);
}

// Middleware: validate session token from header
function authMiddleware(req, res, next) {
  const authHeader = req.headers['x-auth-token'];
  if (!authHeader || typeof authHeader !== 'string') {
    return res.status(401).json({ error: 'Missing token' });
  }

  if (authHeader.length > 1024) {
    return res.status(401).json({ error: 'Token too long' });
  }

  try {
    const dotIndex = authHeader.indexOf('.');
    if (dotIndex === -1 || dotIndex === 0 || dotIndex === authHeader.length - 1) {
      return res.status(401).json({ error: 'Malformed token' });
    }

    // Ensure only one dot separator
    if (authHeader.indexOf('.', dotIndex + 1) !== -1) {
      return res.status(401).json({ error: 'Malformed token' });
    }

    const encodedData = authHeader.substring(0, dotIndex);
    const signature = authHeader.substring(dotIndex + 1);

    // Validate base64 and hex formats before processing
    if (!/^[A-Za-z0-9+/=]+$/.test(encodedData)) {
      return res.status(401).json({ error: 'Invalid encoding' });
    }
    if (!/^[0-9a-f]{64}$/.test(signature)) {
      return res.status(401).json({ error: 'Invalid signature format' });
    }

    const data = Buffer.from(encodedData, 'base64').toString('utf8');

    if (!verifyToken(data, signature)) {
      return res.status(403).json({ error: 'Invalid signature' });
    }

    const parsed = JSON.parse(data);
    if (!parsed || typeof parsed !== 'object' || !parsed.sub || !parsed.role) {
      return res.status(401).json({ error: 'Invalid token payload' });
    }

    req.user = { sub: String(parsed.sub).substring(0, 64), role: String(parsed.role).substring(0, 16), iat: Number(parsed.iat) || 0 };
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Token validation failed' });
  }
}

// Rate limiting state
const rateLimits = new Map();
function rateLimit(req, res, next) {
  const ip = req.ip;
  const now = Date.now();
  const windowMs = 60000;
  const maxRequests = 100;

  if (!rateLimits.has(ip)) {
    rateLimits.set(ip, []);
  }

  const timestamps = rateLimits.get(ip).filter(t => now - t < windowMs);
  if (timestamps.length >= maxRequests) {
    return res.status(429).json({ error: 'Rate limited' });
  }
  timestamps.push(now);
  rateLimits.set(ip, timestamps);
  next();
}

app.use(rateLimit);

// Public: issue a token
app.post('/api/auth/login', (req, res) => {
  const { username, password } = req.body;

  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid credentials format' });
  }

  if (username.length > 64 || password.length > 128) {
    return res.status(400).json({ error: 'Input too long' });
  }

  // Demo: accept any login, real impl would verify against bcrypt-hashed DB
  const payload = { sub: username, iat: Date.now(), role: 'user' };
  const { data, signature } = generateToken(payload);
  const encodedData = Buffer.from(data).toString('base64');
  const token = `${encodedData}.${signature}`;

  TOKEN_STORE.set(username, { token, created: Date.now() });

  return res.json({ token });
});

// Protected: get user profile
app.get('/api/user/profile', authMiddleware, (req, res) => {
  return res.json({
    user: req.user.sub,
    role: req.user.role,
    issued: req.user.iat
  });
});

// Protected: admin action (role check)
app.post('/api/admin/promote', authMiddleware, (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient privileges' });
  }

  const { targetUser, newRole } = req.body;
  if (!targetUser || !newRole || typeof targetUser !== 'string' || typeof newRole !== 'string') {
    return res.status(400).json({ error: 'Invalid request' });
  }

  if (targetUser.length > 64 || newRole.length > 16) {
    return res.status(400).json({ error: 'Input too long' });
  }

  return res.json({ success: true, promoted: targetUser, role: newRole });
});

// Health check (no auth)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: Math.floor(process.uptime()) });
});

const PORT = parseInt(process.env.PORT, 10) || 3000;
if (isNaN(PORT) || PORT < 1 || PORT > 65535) process.exit(1);
app.listen(PORT, '127.0.0.1', () => {
  console.log(`Auth service running on port ${PORT}`);
});
